#include <iostream>
void swapVal(int& a, int& b) {
    int tmp = a; a = b; b = tmp;
}
int main() {
    int x = 5, y = 9;
    swapVal(x, y);
    std::cout << x << ' ' << y << '\n'; // 9 5
}

